// Generated by tools/build-audit-fixes.mjs: rewrites of questions flagged by tools/audit-questions.mjs (options[0] is the correct answer).
const fixes={};
export function applyAuditFixes(courses){for(const c of courses)for(const l of c.lessons)for(const q of l.questions){const f=fixes[q.id];if(!f)continue;q.options=f.options;q.answer=0;if(f.why)q.why=f.why;if(f.prompt)q.prompt=f.prompt;delete q.optionFeedback;}}
